function safeNumber(s){
  const t = String(s).trim();
  const clean = Number(t);
  if (Number.isFinite(clean)) return clean;
  const pref = Number.parseFloat(t);
  return Number.isFinite(pref) ? pref : 0;
}
exports.safeNumber = safeNumber;

function labelEUR(label,x){
  const s = Number(x).toLocaleString('es-ES',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2});
  return `${label}: ${s}`;
}
exports.labelEUR = labelEUR;
